def f_toy(w):
    return np.log1p(np.exp(-w))


w_gd, w_nt = 0.0, 0.0
rows = []
for k in range(0, 11):
    rows.append({"k": k, "GD: w": w_gd, "GD: f": f_toy(w_gd), "Newton: w": w_nt, "Newton: f": f_toy(w_nt)})
    w_gd = w_gd + 4.0 * expit(-w_gd)                                  # eta = 1/L = 4
    w_nt = w_nt + expit(-w_nt) / (expit(w_nt) * expit(-w_nt))         # -f'/f''
